import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

const R = { retried0: false, retried1: false };

test('happy path', async () => {
  const h = await create();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', ...R });
  assert.equal((await h.start()).ok, true);
  assert.equal((await h.start()).ok, false);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.equal(await h.worker('x'), null);
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', ...R });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', ...R });
});

test('retry once then fail', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: true, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: true, retried1: false });
});

test('retry then succeed', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  await h.workDone('worker1');
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true });
});

test('failure while cancelling is recorded, no retry', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  assert.equal((await h.cancel()).ok, true);
  assert.equal((await h.cancel()).ok, false);
  assert.equal((await h.inFlight()).length, 3);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', ...R });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

