  const h = await create();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', ...R, processed: 0 });
  assert.equal((await h.start()).ok, true);
  assert.equal((await h.start()).ok, false);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.equal(await h.worker('x'), null);
  assert.equal((await h.workDone('worker0', 3)).ok, false);
  assert.equal((await h.workDone('worker0', 0)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workDone('worker0', 2);
  const [m] = await h.inFlight();
  assert.deepEqual(m.data, { task: 0, outcome: 'completed', items: 2 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', ...R, processed: 2 });
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', ...R, processed: 3 });
});

test('retry once then fail', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  assert.deepEqual((await h.inFlight())[0].data, { task: 0, outcome: 'failed', items: 0 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: true, retried1: false, processed: 0 });
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0');
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: true, retried1: false, processed: 1 });
});

test('retry then succeed', async () => {
  const h = await create();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  await h.workDone('worker1', 2);
  await h.workDone('worker0', 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true, processed: 4 });
});

